const D = { energy: .6, scale: 1, polish: .5, density: .5, hue: 210, speed: 1, x: .2, y: .5, alpha: 1, style: 'brushed', act: 'rake', seed: 0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const cl=(v,a,b)=>v<a?a:v>b?b:v, md=(a,n)=>((a%n)+n)%n, TAU=Math.PI*2;
const fr=i=>{const s=Math.sin(i*127.1+P.seed*311.7)*43758.5453;return s-Math.floor(s);};
const hsb2rgb=(h,s,b)=>{ h=md(h,360)/60; s=cl(s,0,100)/100; b=cl(b,0,100)/100;
  const c=b*s, x=c*(1-Math.abs((h%2)-1)), m=b-c; let r,g,l;
  if(h<1){r=c;g=x;l=0;} else if(h<2){r=x;g=c;l=0;} else if(h<3){r=0;g=c;l=x;}
  else if(h<4){r=0;g=x;l=c;} else if(h<5){r=x;g=0;l=c;} else {r=c;g=0;l=x;}
  return [(r+m)*255,(g+m)*255,(l+m)*255]; };
if(S.lastBeat==null||K.beat<S.lastBeat)S.lastBeat=K.beat; S.lastBeat=K.beat;

const W=width, Hh=height;
const sty=P.style, act=P.act;
const en=cl(P.energy,0,1), sc=cl(P.scale,.4,2.4), al=cl(P.alpha,0,1);
const pol=cl(P.polish,0,1), dens=cl(P.density,0,1), spd=cl(P.speed,.1,4);
const H=md(P.hue,360), T=K.t*spd;
const TD=K.t*(.45+.55*Math.min(spd,3));

S.bass=(S.bass||0)*.86+(A.bass||0)*.14;
S.tre=(S.tre||0)*.86+(A.treble||0)*.14;

// ---- seeded wrapping fBm field (once per seed) ----
const NZ=160;
if(S.nzK!==P.seed || !S.nz){ S.nzK=P.seed; const F=new Float32Array(NZ*NZ); let amp=1, tot=0;
  for(let o=0;o<4;o++){ const per=4<<o, cell=NZ/per;
    const lv=new Float32Array(per*per);
    for(let k=0;k<per*per;k++) lv[k]=fr(o*977.3+k*1.317+3.7);
    for(let j=0;j<NZ;j++){ const gy=j/cell, jy=Math.floor(gy), fy=gy-jy, vv=fy*fy*(3-2*fy);
      const j0=(jy%per)*per, j1=((jy+1)%per)*per;
      for(let i=0;i<NZ;i++){ const gx=i/cell, ix=Math.floor(gx), fx=gx-ix, uu=fx*fx*(3-2*fx);
        const i0=ix%per, i1=(ix+1)%per;
        const a=lv[j0+i0], b=lv[j0+i1], c=lv[j1+i0], d=lv[j1+i1];
        F[j*NZ+i]+=amp*(a+(b-a)*uu+(c-a)*vv+(a-b-c+d)*uu*vv); } }
    tot+=amp; amp*=0.52; }
  for(let k=0;k<NZ*NZ;k++) F[k]=F[k]/tot;
  S.nz=F; }
const NF=S.nz, CEL=NZ/4;
const nzAt=(x,y)=>{ x*=CEL; y*=CEL;
  let xi=Math.floor(x), yi=Math.floor(y); const fx=x-xi, fy=y-yi;
  xi=md(xi,NZ); yi=md(yi,NZ); const x1=(xi+1)%NZ, y1=(yi+1)%NZ, r0=yi*NZ, r1=y1*NZ;
  const a=NF[r0+xi], b=NF[r0+x1], c=NF[r1+xi], d=NF[r1+x1];
  return a+(b-a)*fx+(c-a)*fy+(a-b-c+d)*fx*fy; };

const BW=Math.max(360,Math.min(720,Math.round(W/2.4))), BH=cl(Math.round(BW*Hh/Math.max(1,W)),60,720);
if(!S.g || S.gk!==BW+'x'+BH){ if(S.g&&S.g.remove)S.g.remove();
  S.g=createGraphics(BW,BH); S.gk=BW+'x'+BH; S.h=new Float32Array(BW*BH); }
const G=S.g, HF=S.h;

// ---- dramaturgy ----
const sec=((K.section|0)%8+8)%8;
let polM, lightRate, panRot;
if(act==='buff'){ polM=.35+.85*(.5+.5*Math.sin(sec*.85+T*.023)); lightRate=.7; panRot=0; }
else if(act==='turn'){ polM=1; lightRate=.28; panRot=1; }
else { polM=1; lightRate=1; panRot=0; }

// ---- the light orbits the panel. The monotonic term is what guarantees the motion floor;
// the wobble is deliberately kept smaller so it can never cancel the advance.
const lAz=cl(P.x,0,1)*TAU + .0170*TD*lightRate + .26*Math.sin(TD*.043*lightRate) + .13*Math.sin(TD*.101*lightRate+1.3);
const lEl=.42+cl(P.y,0,1)*.75 + .10*Math.sin(TD*.059+.7) + .05*Math.sin(TD*.127+2.3) + .03*K.swell;
// `turn` act: the PART rotates on the table instead of the lamp moving
const rot=panRot?(.0130*TD + .10*Math.sin(TD*.037)):0;
const cr=Math.cos(rot), sr=Math.sin(rot);
// A real shop lamp sits at a FINITE distance, so the light direction varies across the
// panel and the highlight is always a travelling band. A directional light on a uniform
// grain lights the whole panel at once — a full-frame flash, which is the one thing the
// no-strobe rule forbids. The lamp is in world space; the part may turn under it.
const lrad=1.02+.14*Math.sin(TD*.037);
const lpx=Math.cos(lAz)*lrad, lpy=Math.sin(lAz)*lrad;
const lph=cl(.26+cl(P.y,0,1)*.70+.06*Math.sin(TD*.059+.7)+.03*K.swell,.14,1.3);
const lpxP=lpx*cr-lpy*sr, lpyP=lpx*sr+lpy*cr;

// ---- style ----
let BASE, spTint, anod=0, blue=0, hammer=0, sun=0;
if(sty==='sunburst'){ BASE=hsb2rgb(H,7,44); spTint=[255,252,244]; sun=1; }
else if(sty==='hammered'){ BASE=hsb2rgb(H,9,43); spTint=[255,248,232]; hammer=1; }
else if(sty==='anodised'){ BASE=hsb2rgb(H,26,34); spTint=[240,246,255]; anod=1; }
else if(sty==='blueprint'){ BASE=hsb2rgb(H+2,62,17); spTint=[190,235,255]; blue=1; }
else { BASE=hsb2rgb(H,6,45); spTint=[255,252,246]; }

// ---- surface height: the panel is never dead flat. Hammered gets real dimples.
const asp=W/Math.max(1,Hh);
const camX=.011*Math.sin(TD*.051+.3), camY=.011*Math.cos(TD*.043+1.9);
const scF=Math.max(.35,sc);
const wf=1.35/scF, dimF=(4.5+dens*7)/scF;
const wavAmp=.030+.045*dens;
for(let j=0;j<BH;j++){
  const sy0=(j/BH-.5)+camY;
  for(let i=0;i<BW;i++){
    const sx0=(i/BW-.5)*asp+camX;
    const sx=sx0*cr-sy0*sr, sy=sx0*sr+sy0*cr;
    let h=(nzAt(sx*wf+3.1, sy*wf+7.7)-.5)*wavAmp + (nzAt(sx*wf*2.7-5.5, sy*wf*2.7+2.2)-.5)*wavAmp*.42;
    if(hammer){
      // planishing: a jittered lattice of hammer strikes, each a shallow dished facet
      const gx=sx*dimF, gy=sy*dimF;
      const c0=Math.floor(gx), r0=Math.floor(gy);
      let best=9e9;
      for(let cc=c0-1;cc<=c0+1;cc++) for(let rr2=r0-1;rr2<=r0+1;rr2++){
        const jx=cc+.5+(fr(cc*7.3+rr2*13.1+600)-.5)*.75, jy=rr2+.5+(fr(cc*7.3+rr2*13.1+601)-.5)*.75;
        const dx=gx-jx, dy=gy-jy, d2=dx*dx+dy*dy;
        if(d2<best) best=d2;
      }
      h+=-.052*Math.sqrt(cl(1-best*.8,0,1));
    }
    HF[j*BW+i]=h;
  }
}

// ---- shade: Ward anisotropic. Roughness is LOW along the grooves and HIGH across them,
// so the highlight stretches PERPENDICULAR to the grain — the thing that sells metal.
G.loadPixels();
const px=G.pixels, sR=spTint[0], sG=spTint[1], sB=spTint[2];
const ax=.030+.085*(1-pol);                  // along the grain — tight
const ay=(.26+.42*(1-pol))*(1+.6*dens);      // across the grain — broad
const NG=13.5;
const spAmt=(.16+2.15*en*en)*polM*(.6+.6*K.intensity)+S.tre*.35*en;
const grainWob=.95*(1-.4*dens);
for(let j=0;j<BH;j++){
  const j0=Math.max(0,j-1)*BW, j1=Math.min(BH-1,j+1)*BW, jr=j*BW;
  const sy0=(j/BH-.5)+camY;
  for(let i=0;i<BW;i++){
    const sx0=(i/BW-.5)*asp+camX;
    const sx=sx0*cr-sy0*sr, sy=sx0*sr+sy0*cr;
    const idx=jr+i;
    // normal from the height field
    const nx=-(HF[jr+Math.min(BW-1,i+1)]-HF[jr+Math.max(0,i-1)])*.5*NG;
    const ny=-(HF[j1+i]-HF[j0+i])*.5*NG;
    const nl=1/Math.sqrt(nx*nx+ny*ny+1);
    const Nx=nx*nl, Ny=ny*nl, Nz=nl;
    // the grain direction field — this is what the style really is
    let tg;
    if(sun) tg=Math.atan2(sy,sx)+1.5707963;                       // circular/sunburst brushing
    else if(hammer) tg=Math.atan2(sy,sx)*.35+(nzAt(sx*3.1/scF+9.9,sy*3.1/scF+4.4)-.5)*3.4;
    else tg=(nzAt(sx*.9/scF+21.3, sy*.9/scF+11.1)-.5)*grainWob;   // straight brush, grain wanders
    tg+=rot;
    const ct=Math.cos(tg), st=Math.sin(tg);
    // per-pixel light vector to the lamp, then the Blinn half-vector against V=(0,0,1)
    let Lx=lpxP-sx, Ly=lpyP-sy, Lz=lph;
    const ll=1/Math.sqrt(Lx*Lx+Ly*Ly+Lz*Lz+1e-9); Lx*=ll; Ly*=ll; Lz*=ll;
    let Hx=Lx, Hy=Ly, Hz=Lz+1;
    const hl=1/Math.sqrt(Hx*Hx+Hy*Hy+Hz*Hz+1e-9); Hx*=hl; Hy*=hl; Hz*=hl;
    // tangent T and bitangent B in the surface
    const ht=Hx*ct+Hy*st;          // H . T   (along the grooves)
    const hb=-Hx*st+Hy*ct;         // H . B   (across the grooves)
    const hn=Hx*Nx+Hy*Ny+Hz*Nz;    // H . N
    const hn2=Math.max(.06,hn*hn);
    const e=((ht*ht)/(ax*ax)+(hb*hb)/(ay*ay))/hn2;
    let spec=Math.min(Math.exp(-e)*spAmt*3.0,2.4);
    // diffuse body, with a fill floor so the panel never sinks to black
    const nl2=Nx*Lx+Ny*Ly+Nz*Lz;
    const lam=cl(.26+.76*Math.max(0,nl2),.12,1.4);
    // fine brush tooth, running ALONG the grain
    const tooth=(nzAt((sx*ct+sy*st)*2.2/scF+41.1, (-sx*st+sy*ct)*96/scF+17.3)-.5)*(.10+.16*dens);
    let R,Gc,B;
    if(blue){
      // machinist's surface chart: the reflectance field as hard iso-bands, no material
      const q=cl(spec*.5+lam*.35,0,1);
      const band=Math.abs(md(q*9,1)-.5)*2;
      const li=Math.pow(cl(1-band*1.5,0,1),1.4);
      const v=.16+.20*q+.80*li;
      R=BASE[0]*(1-li)+sR*v*.9; Gc=BASE[1]*(1-li)+sG*v*.9; B=BASE[2]*(1-li)+sB*v*.9;
    } else if(anod){
      // anodised titanium: oxide thickness follows the topography, so the interference
      // colour is locked to the surface, not to the lamp
      const th=(HF[idx]*11+.5+.20*Math.sin(TD*.021));
      const hh=md(H+th*300,360);
      const c=hsb2rgb(hh,58+22*Math.sin(th*7),42+26*cl(lam,0,1.2));
      R=c[0]*(.62+.5*lam)+sR*spec*.34; Gc=c[1]*(.62+.5*lam)+sG*spec*.34; B=c[2]*(.62+.5*lam)+sB*spec*.34;
    } else {
      const bl=(.46+.62*lam)*(1+tooth);
      R=BASE[0]*bl+sR*spec*.42; Gc=BASE[1]*bl+sG*spec*.42; B=BASE[2]*bl+sB*spec*.42;
    }
    const vx=(i/BW-.5), vy=(j/BH-.5), vg=1-.26*(vx*vx*1.1+vy*vy*1.5);
    R*=vg; Gc*=vg; B*=vg;
    const o=idx*4;
    px[o]=R<0?0:R>255?255:R; px[o+1]=Gc<0?0:Gc>255?255:Gc; px[o+2]=B<0?0:B>255?255:B; px[o+3]=255;
  }
}
G.updatePixels();

noStroke();
if(al<1){ push(); drawingContext.globalAlpha=al; image(G,0,0,W,Hh); pop(); }
else image(G,0,0,W,Hh);
const dc=drawingContext;
blendMode(BLEND); dc.globalAlpha=1; dc.shadowBlur=0; noStroke(); noTint();
